def transform(grid):
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    background = max(counts, key=counts.get)

    other_values = set()
    for row in grid:
        for val in row:
            if val != background and val not in [4, 0]:
                other_values.add(val)
    marker = list(other_values)[0]

    output = [row[:] for row in grid]

    h, w = len(grid), len(grid[0]) if grid else 0
    for r in range(h):
        markers = [c for c in range(w) if grid[r][c] == marker]

        if not markers:
            continue

        for m_col in markers:
            start_col = m_col - 2
            for dc in range(5):
                nc = start_col + dc
                if 0 <= nc < w:
                    if dc < 2:
                        output[r][nc] = 4
                    else:
                        output[r][nc] = 0

    return output

